    sr=sorted(i for i in range(H) if len(set(a[i]))==1)
    sc=sorted(j for j in range(W) if len({a[i][j] for i in range(H)})==1)
    sepv=a[sr[0]][0]; bg_=Counter(x for row in a for x in row).most_common(1)[0][0]
    R=[-1]+sr+[H]; C=[-1]+sc+[W]
    wins=[]
    for r1,r2 in zip(R[:-1],R[1:]):
        for c1,c2 in zip(C[:-1],C[1:]):
            cnt=Counter(a[i][j] for i in range(r1+1,r2) for j in range(c1+1,c2))
            col=max(((k,v) for k,v in cnt.items() if k not in (bg_,sepv)), default=(None,0))[1]
            if col>0: wins.append((col,r1,r2,c1,c2))
    mx=max(wins)
    out=[[a[i][j] if (i in sr or j in sc) else 0 for j in range(W)] for i in range(H)]
    for i in range(H):
        for j in range(W):
            if i in sr or j in sc: out[i][j]=a[i][j]
    for col,r1,r2,c1,c2 in wins:
        if col!=mx: continue
        for i in range(r1,r2):
            for j in range(c1,c2):
                out[i][j]=col
    return out
