import json
from collections import Counter
def f(inp):
    a=[row[:] for row in inp]; H=len(a); W=len(a[0])
    sr=sorted(i for i in range(H) if len(set(a[i]))==1)
    sc=sorted(j for j in range(W) if len({a[i][j] for i in range(H)})==1)
    sepv=a[sr[0]][0]; bg_=Counter(x for row in a for x in row).most_common(1)[0][0]
    rows_bounds=[(0,sr[0])] + [(sr[k]+1,sr[k+1]) for k in range(len(sr)-1)] + [(sr[-1]+1,H)]
    cols_bounds=[(0,sc[0])] + [(sc[k]+1,sc[k+1]) for k in range(len(sc)-1)] + [(sc[-1]+1,W)]
    wins=[]
    for rb in rows_bounds:
        for cb in cols_bounds:
            cnt=Counter(a[i][j] for i in range(rb[0],rb[1]) for j in range(cb[0],cb[1]))
            col=max(((k,v) for k,v in cnt.items() if k not in (bg_,sepv)), default=(None,0))
            if col[1]>0: wins.append((col[1],col[0],rb[0],rb[1],cb[0],cb[1]))
    mx=max(wins,key=lambda t:t[0])[0]
    out=[[bg_]*W for _ in range(H)]
    for i in sr: out[i]=[sepv]*W
    for j in sc:
        for i in range(H): out[i][j]=sepv
    for n,c,r1,r2,c1,c2 in wins:
        if n==mx:
            for i in range(r1,r2):
                for j in range(c1,c2): out[i][j]=c
    return out
